    BNET_ERROR_1001_HTML = "<html><body><p align=\"CENTER\">Kan ikke oprette forbindelse. Prøv venligst igen senere. Hvis problemet fortsætter, bedes du kontakte teknisk støtte på: <a href=\"http://us.blizzard.com/support/index.xml?gameId=11&amp;rootCategoryId=2316\">http://us.blizzard.com/support/index.xml?gameId=11&amp;rootCategoryId=2316</a></p></body></html>",
    BNET_ERROR_1002_HTML = "<html><body><p align=\"CENTER\">Kan ikke oprette forbindelse. Prøv venligst igen senere. Hvis problemet fortsætter, bedes du kontakte teknisk støtte på: <a href=\"http://us.blizzard.com/support/index.xml?gameId=11&amp;rootCategoryId=2316\">http://us.blizzard.com/support/index.xml?gameId=11&amp;rootCategoryId=2316</a></p></body></html>",
    BNET_ERROR_11 = "Adgang til denne konto er i øjeblikket begrænset af forældrekontrol. Du kan ændre dine kontrolindstillinger via din onlinekontoadministration.",
    BNET_ERROR_28_HTML = "<html><body><p align=\"CENTER\">Kan ikke validere spilversionen.  Dette kan skyldes filkorruption eller indblanding fra et andet program.  Besøg venligst <a href=\"http://us.blizzard.com/support/article.xml?articleId=21031\">http://us.blizzard.com/support/article.xml?articleId=21031</a> for mere information og mulige løsninger på dette problem.</p></body></html>",
    BNET_ERROR_3 = "Vi kunne ikke få dig indlogget med det, du lige har indtastet. Prøv venligst igen.",
    BNET_ERROR_3003 = "Der er opstået en fejl. Prøv igen senere.",
    BNET_ERROR_3021 = "Der er opstået en fejl. Prøv igen senere.",
    BNET_ERROR_33 = "Snestorm-tjenesterne er under vedligeholdelse. Prøv venligst igen senere.",
    BNET_ERROR_34200 = "Der er i øjeblikket ingen tilgængelige servere.",
    BNET_ERROR_37_HTML = "<html><body><p align=\"CENTER\">Indlogningsserveren er i øjeblikket travl. Prøv venligst igen senere. Hvis problemet fortsætter, bedes du kontakte Teknisk Støtte på: <a href=\"http://us.blizzard.com/support/index.xml?gameId=11&amp;rootCategoryId=2316\">http://us.blizzard.com/support/index.xml?gameId=11&amp;rootCategoryId=2316</a></p></body></html>",
    BNET_ERROR_38 = "Du skal oprette et KampTag, før du kan forbinde til Snestorm-tjenesterne.",
