    BNET_ERROR_40014_HTML = "(Kun CN) Fiasko i nationalt ID-verificering",
    BNET_ERROR_42003 = "Din konto er blevet låst af sikkerhedsmæssige årsager.",
    BNET_ERROR_50_HTML = "<html><body><p align=\"CENTER\">Du har brugt din forudbetalte tid til denne konto. Besøg venligst <a href=\"http://www.worldofwarcraft.com/account\">www.worldofwarcraft.com/account</a> for at købe mere, så du kan fortsætte med at spille.</p></body></html>",
    BNET_ERROR_52_HTML = "<html><body><p align=\"CENTER\">Denne Verden af Krigskunst-konto er blevet lukket og er ikke længere tilgængelig til brug.  Gå venligst til <a href=\"http://www.worldofwarcraft.com/misc/banned.html\">http://www.worldofwarcraft.com/misc/banned.html</a> for yderligere information.</p></body></html>",
    BNET_ERROR_53_HTML = "<html><body><p align=\"CENTER\">Denne Verden af Krigskunst-konto er midlertidigt suspenderet.%s Gå venligst til <a href=\"http://www.worldofwarcraft.com/misc/banned.html\">http://www.worldofwarcraft.com/misc/banned.html</a> for yderligere information.</p></body></html>",
    BNET_ERROR_57_HTML = "<html><body><p align=\\\"CENTER\\\">Adgang til din konto er midlertidigt deaktiveret. Kontakt venligst støtte for mere information på: <a href=\\\"https://www.worldofwarcraft.com/account/account-error.html\\\">https://www.worldofwarcraft.com/account/account-error.html</a></p></body></html>",
    BNET_ERROR_58 = "Du har lagt en lås på din konto. Du kan ændre din låsestatus ved at ringe til dit kontos låsetelefonnummer.",
    BNET_ERROR_59_HTML = "<html><body><p align=\"CENTER\">Denne Verden af Krigskunst-konto er midlertidigt lukket på grund af en tilbageførsel på dens abonnement.  Se venligst <a href=\"http://us.blizzard.com/support/article/chargeback\">http://us.blizzard.com/support/article/chargeback</a> for yderligere information.</p></body></html>",
