    TURN_IN_ITEMS = "Kræver genstande:",
    TURN_IN_QUEST = "Aflever",
    TUTORIAL1 = "Questgivere har udråbstegn (|TInterface\\\\OptionsFrame\\\\UI-OptionsFrame-NewFeatureIcon:0|t) over hovedet. |cffffd200Højreklik|r på dem for at få en quest.",
    TUTORIAL10_DWARF = "Du har fået en quest om at dræbe |cffffd200Klippekæbe-indtrængere|r. \\nBrug minikortet i øverste højre hjørne til at finde vej.",
    TUTORIAL10_GNOME = "Du har fået en quest om at dræbe |cffffd200Vanvittige Spedalske Gnomer|r. \\nBrug minikortet i øverste højre hjørne til at finde vej.",
    TUTORIAL10_HUMAN = "Du har fået en quest om at dræbe |cffffd200Sortklippe-kampworger|r. De er nord for klosteret (hvor du er nu).|nBrug minikortet i øverste højre hjørne til at finde vej.",
    TUTORIAL10_NIGHTELF = "Du har fået en quest om at dræbe |cffffd200Unge Natsabler|r. \\nBrug minikortet i øverste højre hjørne til at finde vej.",
    TUTORIAL10_ORC = "Du har fået en quest om at dræbe |cffffd200Plettet Vildsvin|r. \\nBrug minikortet i øverste højre hjørne til at finde vej.",
    TUTORIAL10_SCOURGE = "Du har fået en quest om at dræbe |cffffd200Tankeløse Zombier|r. \\nBrug minikortet i øverste højre hjørne til at finde vej.",
    TUTORIAL10_TAUREN = "Du har fået en quest om at dræbe |cffffd200Børsterygge-indtrængere|r. \\nBrug minikortet i øverste højre hjørne til at finde vej.",
    TUTORIAL10_TROLL = "Du har fået en quest om at dræbe |cffffd200Tiki-mål|r. \\nBrug minikortet i øverste højre hjørne til at finde vej.",
    TUTORIAL11_DWARF = "Besejr flere |cffffd200Klippekæbe-indtrængere|r!",
    TUTORIAL11_GNOME = "Besejr flere |cffffd200Vanvittige Spedalske Gnomer|r!",
    TUTORIAL11_HUMAN = "Besejr flere |cffffd200Sortklippe-worger|r!",
    TUTORIAL11_NIGHTELF = "Besejr flere |cffffd200Unge Natsabler|r!",
    TUTORIAL11_ORC = "Besejr flere |cffffd200Plettet Vildsvin|r!",
    TUTORIAL11_SCOURGE = "Besejr flere |cffffd200Tankeløse Zombier|r!",
    TUTORIAL11_TAUREN = "Besejr flere |cffffd200Børsterygge-indtrængere|r!",
    TUTORIAL11_TROLL = "Besejr flere |cffffd200Tiki-mål|r!",
    TUTORIAL12 = "Du kan drikke for at genvinde din mana hurtigere. |cffffd200Højreklik|r på en drik for at drikke den.|n|nDu behøver ikke at drikke, hvis din klasse ikke bruger mana.",
    TUTORIAL13 = "Du kan lære et nyt talent i talent-grænsefladen.|n|nÅbn begavelsessiden ved at klikke på den pulserende |cffffd200Begavelser-knappen|r på din handlingslinje.",
    TUTORIAL14 = "Du kan gå til din klasses træner for at lære nye færdigheder. |cffffd200Højreklik|r på trænere for at tale med dem.|n|nTrænere findes i mange byer og altid i dit startområde. Du skal måske søge lidt rundt for at finde din træner.",
    TUTORIAL15 = "Du kan flytte besværgelser og evner til din handlingslinje ved at klikke på |cffffd200Besværgelsesbog & Evner-knappen|r nederst i midten af skærmen og derefter trække evne-ikonet til din handlingslinje.|n|nDu kan også bruge en besværgelse eller evne direkte fra besværgelsesbogen ved at klikke på den.",
    TUTORIAL16 = "Du kan se dit ry hos forskellige grupper i verden under Omdømme-fanen.|n|nKlik på |cffffd200Karakterinfo-knappen|r for at finde Omdømme-fanen.",
    TUTORIAL17 = "Du kan svare spilleren ved at trykke på R-tasten og derefter skrive en besked, eller ved at skrive /w <theirname> og derefter beskeden.",
    TUTORIAL18 = "Du kan invitere en anden spiller til din gruppe ved at |cffffd200Højreklikke|r på deres portræt og vælge |cffffd200Inviter|r fra pop op-menuen.|n|nDu kan forlade en gruppe ved at højreklikke på dit eget portræt og vælge muligheden for at forlade gruppen.",
    TUTORIAL19 = "Det er et andet rigtigt menneske, der spiller en karakter. Det kan du se på det blå navn over hovedet.",
    TUTORIAL1_DWARF = "Questgivere har udråbstegn (|TInterface\\\\OptionsFrame\\\\UI-OptionsFrame-NewFeatureIcon:0|t) over hovedet. Du kan få en quest ved at tale med |cffffd200Joren Jernlager|r.|n|nFor at tale med  |cffffd200Joren Jernlager|r skal du |cffffd200Højreklikke|r på ham.",
    TUTORIAL1_GNOME = "Questgivere har udråbstegn (|TInterface\\\\OptionsFrame\\\\UI-OptionsFrame-NewFeatureIcon:0|t) over hovedet. Du kan få en quest ved at tale med |cffffd200Nevin Vridskruenøgle|r.|n|nFor at tale med  |cffffd200Nevin Vridskruenøgle|r skal du |cffffd200Højreklikke|r på ham.",
    TUTORIAL1_HUMAN = "Questgivere har udråbstegn (|TInterface\\\\OptionsFrame\\\\UI-OptionsFrame-NewFeatureIcon:0|t) over hovedet. Du kan få en quest ved at tale med |cffffd200Marskal McBride|r.|n|nFor at tale med  |cffffd200Marskal McBride|r skal du |cffffd200Højreklikke|r på ham.",
    TUTORIAL1_NIGHTELF = "Questgivere har udråbstegn (|TInterface\\\\OptionsFrame\\\\UI-OptionsFrame-NewFeatureIcon:0|t) over hovedet. Du kan få en quest ved at tale med |cffffd200Ilthalæne|r.|n|nFor at tale med  |cffffd200Ilthalæne|r skal du |cffffd200Højreklikke|r på hende.",
    TUTORIAL1_ORC = "Questgivere har udråbstegn (|TInterface\\\\OptionsFrame\\\\UI-OptionsFrame-NewFeatureIcon:0|t) over hovedet. Du kan få en quest ved at tale med |cffffd200Kaldtonk|r.|n|nFor at tale med  |cffffd200Kaldtonk|r skal du |cffffd200Højreklikke|r på ham.",
    TUTORIAL1_SCOURGE = "Questgivere har udråbstegn (|TInterface\\\\OptionsFrame\\\\UI-OptionsFrame-NewFeatureIcon:0|t) over hovedet. Du kan få en quest ved at tale med |cffffd200Agata Ligsten|r.|n|nFor at tale med  |cffffd200Agata Ligsten|r skal du |cffffd200Højreklikke|r på hende.",
    TUTORIAL1_TAUREN = "Questgivere har udråbstegn (|TInterface\\\\OptionsFrame\\\\UI-OptionsFrame-NewFeatureIcon:0|t) over hovedet. Du kan få en quest ved at tale med |cffffd200Høvding Falkevind|r.|n|nFor at tale med  |cffffd200Høvding Falkevind|r skal du |cffffd200Højreklikke|r på ham.",
    TUTORIAL1_TROLL = "Questgivere har udråbstegn (|TInterface\\\\OptionsFrame\\\\UI-OptionsFrame-NewFeatureIcon:0|t) over hovedet. Du kan få en quest ved at tale med |cffffd200Jin'taler|r.|n|nFor at tale med  |cffffd200Jin'taler|r skal du |cffffd200Højreklikke|r på ham.",
    TUTORIAL2 = "Brug A-, S-, D- og W-tasterne til at flytte din karakter.",
    TUTORIAL20 = "|cffffd200Højreklik|r på en genstand i handlerpanelet køber genstanden, hvis du har nok penge.|n|nMens handlerpanelet er åbent, sælger du genstanden ved at højreklikke på en genstand i din rygsæk.",
    TUTORIAL21 = "Du kan se dine nuværende quests ved at klikke på |cffffd200Questlogbog-knappen|r nederst i midten af skærmen.|n|nDu kan se placeringen af quests ved at klikke på |cffffd200Verdenskort-knappen|r øverst til højre på skærmen.",
    TUTORIAL22 = "Hvis der er en anden spiller, du har nydt at spille sammen med, så tilføj vedkommende til din venneliste! Klik på |cffffd200Social-knappen|r og tilføj dem til din venneliste.|n|nDu kan kun tilføje venner fra dit eget rige.",
    TUTORIAL23 = "Du kan sende en besked ved at trykke på Skriv-tasten, skrive en besked og derefter trykke Skriv igen. Andre spillere i nærheden hører, hvad du siger.",
    TUTORIAL24 = "Du kan udstyre genstande ved først at klikke på |cffffd200Karakterinfo-knappen|r nederst på skærmen og derefter på |cffffd200Rygsæk-knappen|r nederst til højre på din skærm.|n|nTræk derefter bare en genstand, der kan udstyres, fra din rygsæk over på din karakter.",
    TUTORIAL25 = "Du er nu et spøgelse. Du kan vende tilbage til livet ved enten at finde dit lig eller ved at tale med en åndehealer i nærheden.|n|nDit lig vises som et ikon på minikortet øverst til højre på skærmen.",
    TUTORIAL26 = "Du er udhvilet. At være udhvilet giver dig en midlertidig bonus til erfaring fra at dræbe monstre.",
    TUTORIAL27 = "Hvis du vover dig ud i dybe og ukortlagte farvande, vil du se en Træthedsbarre. Hvis du bliver helt træt, begynder du at drukne.",
    TUTORIAL28 = "Svømning minder meget om at gå, bortset fra at du kan styre opad og nedad ved at holde |cffffd200højre museknap|r nede og kigge i den retning, du vil hen.",
    TUTORIAL29 = "Du vil se en Åndebarre dukke op, når din karakter bliver nedsænket i vand. Hvis du løber tør for ånde, begynder du at drukne.",
    TUTORIAL3 = "Du kan dreje din karakter ved at |cffffd200holde højre museknap nede|r og bevæge musen.|n|nDu kan kigge rundt ved at holde venstre museknap nede og bevæge musen.",
    TUTORIAL30 = "Du hviler nu, hvilket ses på at dit portræt lyser gult. Tid brugt på at hvile eller være logget af giver dig en midlertidig bonus til erfaring fra at dræbe monstre.|n|nDu kan hurtigt vende tilbage til kroer for at hvile ved at bruge din hjemsten.",
    TUTORIAL31 = "Hjemstene kan bruges til at transportere dig fra din nuværende placering til kroen, hvor du har sat din hjemsten.",
    TUTORIAL32 = "Du deltager i spiller mod spiller-kamp. Mens du deltager i spiller mod spiller-kamp, vil symbolet for dit forbund dukke op ved siden af dit portræt, og du kan blive angrebet af fjendtlige spillere.",
    TUTORIAL33 = "Du kan trykke på |cffffd200Spacebar|r for at få din karakter til at hoppe. Du kan bruge springende til at komme forbi forhindringer eller bare for sjov.",
    TUTORIAL34 = "TILLYKKE! Du har fuldført din første quest!",
    TUTORIAL35 = "Dette er en flyvemester, som træner flyvende bæster til at bære passagerer fra et sted til et andet. For en beskeden takst kan du hurtigt rejse til andre flyvemestre, som du har talt med tidligere.|n|nNår du opdager en ny by, vil det at finde flyvemesteren gøre det nemt for dig at vende tilbage i fremtiden.",
    TUTORIAL36 = "Holdbarheden på en af dine genstande er ved at blive lav. Karakterikonet under dit minikort viser den beskadigede genstand med gul farve.|n|nFind en handler i byen og få repareret genstanden, før den går i stykker.",
    TUTORIAL37 = "En af dine genstande er gået i stykker! Karakterikonet under dit minikort viser den ødelagte genstand med rød farve.|n|nDu kan få genstanden repareret af en handler i byen. Indtil du gør det, får du ingen fordel af genstanden.",
    TUTORIAL38 = "Din karakter kan lære erhverv som Madlavning eller Smedning, som vil gøre det muligt for dig at finde eller fremstille værdifulde genstande.|n|nFor at lære mere om erhverv, så spørg en vagt i en storby om vej til erhvervstrænerne.",
    TUTORIAL39 = "Du vil måske invitere andre spillere til at gå sammen med dig, så det bliver lettere at overvinde dine fjender.|n|nMange svære quests kan hurtigt fuldføres i en gruppe, da questkredit deles af gruppen. Desuden giver grupper bonus-erfaring i forhold til solospillere.",
    TUTORIAL40 = "Du har lært en ny besværgelse eller evne! Brug |cffffd200Besværgelsesbog & Evner-knappen|r nederst på skærmen for at åbne din Besværgelsesbog. |cffffd200Venstreklik og træk|r en besværgelse eller evne for at flytte den til din Handlingslinje.\\n\\nBesværgelsesbogen er organiseret med passive besværgelser efter de aktive.",
    TUTORIAL41 = "Du har accepteret en elite-quest. Sådanne quests løses bedst i en gruppe, for de fører dig ind i områder, hvor der lever elite-væsener.|n|nElite-væsener er betydeligt sejere end almindelige monstre; til gengæld er de værd mere erfaring. Du kan kende et elite-væsen på den gyldne drage-kant omkring dets portræt.",
    TUTORIAL42 = "For at komme i gang bør du begynde en |cffffd200Quest|r.|n|nDer er en questgiver lige foran dig. Vejledningstips vil hjælpe dig på vejen.|n|nTak for at spille, og held og lykke på dine eventyr!",
    TUTORIAL43 = "En questgiver med et grå '!' over hovedet har en quest, som du er for lavt niveau til at acceptere. Kig forbi igen, når du har fået et par niveauer.",
    TUTORIAL44 = "Du har fået et distancevåben. For at bruge det skal du først udstyre våbnet ved at åbne din |cffffd200Karakterinfo|r og din |cffffd200Rygsæk|r og trække genstanden over på din karakter.|n|nÅbn derefter din |cffffd200Besværgelsesbog|r og træk evnen |cffffd200Skyd|r eller |cffffd200Kast|r over på din handlingslinje.|n|nKun jægere, krigere og snigmordere må bruge distancevåben. Magikere, præster og hekser må bruge tryllestave.",
    TUTORIAL45 = "Du kan ikke affyre buer og geværer uden ammunition. For at købe ammunition skal du besøge en gevær-købmand eller buekøbmand i en by. For at udstyre ammunition skal du |cffffd200højreklikke|r på den.",
    TUTORIAL46 = "Du er nu med i en razziagruppe: en gruppe med en øget grænse på 40 medlemmer, dog normalt 10 eller 25. Razziagrupper er nødvendige for at komme ind i de mest udfordrende fangehuller eller for at besejre de mest kraftfulde fjender, typisk på højt niveau.|n|n|cffff2020Mens du er i en razziagruppe, får du ingen questkredit for de fleste quests. For at forlade en razziagruppe skal du højreklikke på dit karakterportræt og vælge Forlad gruppe.|r",
    TUTORIAL47 = "Du har fået adgang til totembarren! Du får en handlingsknap på denne barre, hver gang du får adgang til et nyt totemelement.|n|nDenne barre kan rumme én totembesværgelse pr. totemelement. På højere niveau får du evnen til at smide flere totems ned på én gang.",
    TUTORIAL48 = "Du er nu i kø for at komme ind på en slagmark.  Du kan tjekke din status ved at flytte musemarkøren hen over ikonet på dit minikort.",
    TUTORIAL49 = "Du er nu berettiget til at deltage i kamp. Klik på \"Skriv i Kamp\" i dialogen eller højreklik på slagmarksikonet på minikortet.",
    TUTORIAL4_DWARF = "|cffffd200Klippekæbe-angriberne|r er i nærheden. |cffffd200Venstreklik|r på en vilkårlig |cffffd200Klippekæbe-angriber|r for at målrette den.",
    TUTORIAL4_GNOME = "De |cffffd200Vanvittige Spedalske Gnomer|r er i nærheden. |cffffd200Venstreklik|r på en vilkårlig |cffffd200Vanvittig Spedalsk Gnome|r for at målrette den.",
    TUTORIAL4_HUMAN = "De |cffffd200Sortklippe Kampworger|r er i nærheden. |cffffd200Venstreklik|r på en vilkårlig |cffffd200Sortklippe Kampvarg|r for at målrette den.",
    TUTORIAL4_NIGHTELF = "De |cffffd200Unge Natsabler|r er i nærheden. |cffffd200Venstreklik|r på en vilkårlig |cffffd200Ung Natsabel|r for at målrette den.",
    TUTORIAL4_ORC = "De |cffffd200Plettede Vildsvin|r er i nærheden. |cffffd200Venstreklik|r på et vilkårligt |cffffd200Plettet Vildsvin|r for at målrette det.",
    TUTORIAL4_SCOURGE = "De |cffffd200Tankeløse Zombier|r er i nærheden. |cffffd200Venstreklik|r på en vilkårlig |cffffd200Tankeløs Zombi|r for at målrette den.",
    TUTORIAL4_TAUREN = "De |cffffd200Børsterygge-angriberne|r er i nærheden. |cffffd200Venstreklik|r på en vilkårlig |cffffd200Børsterygge-angriber|r for at målrette den.",
    TUTORIAL4_TROLL = "De |cffffd200Tiki-mål|r er i nærheden. |cffffd200Venstreklik|r på et vilkårligt |cffffd200Tiki-mål|r for at målrette det.",
    TUTORIAL5 = "For at bekæmpe dine fjender skal du klikke på besværgelserne på din |cffffd200Handlingslinje|r.",
    TUTORIAL50 = "Du har nu en nøglering til at holde dine nøgler. Denne |cffffd200Nøgleringsknap|r vises til venstre for dine tasker på din handlingslinje.",
    TUTORIAL51 = "Du kan gå ind i fangehuller eller finde grupper til fangehuller ved hjælp af |cffffd200Fangehulssøgeren|r. Fangehulssøgeren åbnes via øjeknappen nær midten af din handlingslinje.",
    TUTORIAL52 = "Tillykke, du har fået dit første Kampkæledyr. Denne lille fyr vil følge dig under alle dine eventyr i Azeroth og videre.|n|nDu kan se alle dine Kampkæledyr ved at klikke på |cffffd200Samlinger|r-knappen og derefter finde fanen |cffffd200Kæledyrsdagbog|r.",
    TUTORIAL53 = "Tillykke, du har lært at tilkalde dit første ridedyr. Denne mægtige hest vil bære dig gennem alle dine eventyr i Azeroth og videre.|n|nFor at se alle dine ridedyr skal du klikke på |cffffd200Samlinger|r-knappen og lede efter fanen |cffffd200Ridedyr|r. Du kan trække dit yndlingsridedyr over på din handlingslinje for at tilkalde det lettere.",
    TUTORIAL54 = "Du har tiltrukket dig opmærksomheden fra en fjendtlig skabning.|n|nEn rød glød betyder, at skabningen angriber dig. En gul glød betyder, at du er i fare for at blive angrebet. En orange glød betyder, at skabningen angriber dig, men snart kan skifte mål.",
    TUTORIAL55 = "Tillykke! Du har dræbt nok mål til at fuldføre din quest|n|nVend tilbage til din questgiver for at hente din belønning.",
    TUTORIAL55_DWARF = "Tillykke! Du har dræbt nok |cffffd200Klippekæbe-angribere|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Joren Jernlager|r for at hente din belønning.",
    TUTORIAL55_GNOME = "Tillykke! Du har dræbt nok |cffffd200Vanvittige Spedalske Gnomer|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Nevin Vridnøgle|r for at hente din belønning.",
    TUTORIAL55_HUMAN = "Tillykke! Du har dræbt nok |cffffd200Sortklippe Kampworger|r til at fuldføre din quest.|n|nVend tilbage til |cffffd200Marskal McBride|r for at hente din belønning.",
    TUTORIAL55_NIGHTELF = "Tillykke! Du har dræbt nok |cffffd200Unge Natsabler|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Ilthalæne|r for at hente din belønning.",
    TUTORIAL55_ORC = "Tillykke! Du har dræbt nok |cffffd200Plettede Vildsvin|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Gornek|r for at hente din belønning.",
    TUTORIAL55_SCOURGE = "Tillykke! Du har dræbt nok |cffffd200Tankeløse Zombier|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Bedemand Morder|r for at hente din belønning.",
    TUTORIAL55_TAUREN = "Tillykke! Du har dræbt nok |cffffd200Børsterygge-angribere|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Grull Falkevind|r for at hente din belønning.",
    TUTORIAL55_TROLL_DRUID = "Tillykke! Du har dræbt nok |cffffd200Tiki-mål|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Zen'Tabra|r for at hente din belønning.",
    TUTORIAL55_TROLL_HUNTER = "Tillykke! Du har dræbt nok |cffffd200Tiki-mål|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Ortezza|r for at hente din belønning.",
    TUTORIAL55_TROLL_MAGE = "Tillykke! Du har dræbt nok |cffffd200Tiki-mål|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Soratha|r for at hente din belønning.",
    TUTORIAL55_TROLL_PRIEST = "Tillykke! Du har dræbt nok |cffffd200Tiki-mål|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Tunari|r for at hente din belønning.",
    TUTORIAL55_TROLL_ROGUE = "Tillykke! Du har dræbt nok |cffffd200Tiki-mål|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Legati|r for at hente din belønning.",
    TUTORIAL55_TROLL_SHAMAN = "Tillykke! Du har dræbt nok |cffffd200Tiki-mål|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Nekali|r for at hente din belønning.",
    TUTORIAL55_TROLL_WARLOCK = "Tillykke! Du har dræbt nok |cffffd200Tiki-mål|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Voldreka|r for at hente din belønning.",
    TUTORIAL55_TROLL_WARRIOR = "Tillykke! Du har dræbt nok |cffffd200Tiki-mål|r til at fuldføre din quest|n|nVend tilbage til |cffffd200Nortet|r for at hente din belønning.",
    TUTORIAL56 = "Øverst til venstre på din skærm finder du din helbredsbarre i grøn. Når din helbredsbarre når nul, dør du, så vær forsigtig.|n|nUnder din helbredsbarre er der en anden barre, der viser den ressource, din klasse bruger til at drive dine specielle evner, såsom raseri, energi eller mana.",
    TUTORIAL57_HUMAN = "Husk at besøge |cffffd200Marskal McBride|r. Han har en quest til dig! |cffffd200Højreklik|r på ham, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_ORC = "Husk at besøge |cffffd200Gornek|r. Han har en quest til dig! |cffffd200Højreklik|r på ham, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_SCOURGE = "Husk at besøge |cffffd200Bedemand Morder|r. Han har en quest til dig! |cffffd200Højreklik|r på ham, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_TAUREN = "Husk at besøge |cffffd200Grull Falkevind|r. Han har en quest til dig! |cffffd200Højreklik|r på ham, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_TROLL_DRUID = "Husk at besøge |cffffd200Zen'Tabra|r.  Hun har en quest til dig! |cffffd200Højreklik|r på hende, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_TROLL_HUNTER = "Husk at besøge |cffffd200Ortezza|r.  Hun har en quest til dig! |cffffd200Højreklik|r på hende, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_TROLL_MAGE = "Husk at besøge |cffffd200Soratha|r.  Han har en quest til dig! |cffffd200Højreklik|r på ham, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_TROLL_PRIEST = "Husk at besøge |cffffd200Tunari|r.  Hun har en quest til dig! |cffffd200Højreklik|r på hende, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_TROLL_ROGUE = "Husk at besøge |cffffd200Legati|r.  Han har en quest til dig! |cffffd200Højreklik|r på ham, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_TROLL_SHAMAN = "Husk at besøge |cffffd200Nekali|r.  Hun har en quest til dig! |cffffd200Højreklik|r på hende, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_TROLL_WARLOCK = "Husk at besøge |cffffd200Voldreka|r.  Han har en quest til dig! |cffffd200Højreklik|r på ham, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL57_TROLL_WARRIOR = "Husk at besøge |cffffd200Nortet|r.  Han har en quest til dig! |cffffd200Højreklik|r på ham, når din markør er et |cffffd200Gult Spørgsmålstegn|r.",
    TUTORIAL58 = "Dine tasker er fulde, så du kan ikke samle mere plyndring op. For at frigøre plads i taskerne skal du besøge handlerkarakterer og sælge dem noget af dit skrald.|n|nDer er normalt handlere i alle byer, landsbyer eller forposter.",
    TUTORIAL59 = "For at frigøre taskeplads eller tjene nogle penge kan du sælge nogle af de genstande, du har samlet.|n|nFind en handler og |cffffd200højreklik|r på dem. Åbn derefter dine tasker og |cffffd200højreklik|r på de genstande, du vil sælge.",
    TUTORIAL5_DRUID = "For at bekæmpe dine fjender skal du klikke på |cffffd200Vrede|r på din |cffffd200Handlingslinje|r.",
    TUTORIAL5_HUNTER = "For at bekæmpe dine fjender skal du klikke på |cffffd200Arkanskud|r på din |cffffd200Handlingslinje|r.",
    TUTORIAL5_MAGE = "For at bekæmpe dine fjender skal du klikke på |cffffd200Frostild-bolt|r på din |cffffd200Handlingslinje|r.",
    TUTORIAL5_PALADIN = "For at bekæmpe dine fjender skal du klikke på |cffffd200Korsfarerslag|r på din |cffffd200Handlingslinje|r.",
    TUTORIAL5_PRIEST = "For at bekæmpe dine fjender skal du klikke på |cffffd200Straf|r på din |cffffd200Handlingslinje|r.",
    TUTORIAL5_ROGUE = "For at bekæmpe dine fjender skal du klikke på |cffffd200Ondskabsfuldt Slag|r på din |cffffd200Handlingslinje|r.",
    TUTORIAL5_SHAMAN = "For at bekæmpe dine fjender skal du klikke på |cffffd200Lynbolt|r på din |cffffd200Handlingslinje|r.",
    TUTORIAL5_WARLOCK = "For at bekæmpe dine fjender skal du klikke på |cffffd200Skyggebolt|r på din |cffffd200Handlingslinje|r.",
    TUTORIAL5_WARRIOR = "For at bekæmpe dine fjender skal du klikke på |cffffd200Angreb|r på din |cffffd200Handlingslinje|r.",
    TUTORIAL6 = "Mange af dine evner er våbenangreb eller kampbesværgelser.|n|nAfhængigt af din klasse kan du have defensive evner eller endda helbredende besværgelser på din handlingslinje.",
    TUTORIAL60 = "Husk, at din karakter har specielle evner på handlingslinjen nederst på skærmen.|n|nAt bruge disse evner dræber en fjende meget hurtigere, end hvis du bare svinger dit våben.",
    TUTORIAL61_DRUID = "Som druide kan du |cffffd200skifte skikkelse|r til forskellige former, hver med unikke evner og sin egen ressource. Din første skikkelse, Kat, øger din nærkampsskade.",
    TUTORIAL61_HUNTER = "Du har nu en |cffffd200Kæledyrs Handlingslinje|r for bedre kontrol over dit kæledyr. Derudover har du evnen til at |cffffd200tæmme bæster|r for at få nye kæledyr",
    TUTORIAL61_PALADIN = "Du kan nu bruge |cffffd200Hellig Kraft|r. Dit Korsfarerslag genererer Hellig Kraft, og dit Herlighedens Ord kan bruge den.",
    TUTORIAL61_SHAMAN = "Du har lært din første |cffffd200totem|r! Forskellige slags totems giver forskellige slags fordele. Til sidst vil du kunne bruge fire forskellige totems på én gang.",
    TUTORIAL61_SPELLID_DRUID = "768",
    TUTORIAL61_SPELLID_HUNTER = "93321",
    TUTORIAL61_SPELLID_PALADIN = "85673",
    TUTORIAL61_SPELLID_SHAMAN = "8075",
    TUTORIAL61_SPELLID_WARLOCK = "93375",
    TUTORIAL61_WARLOCK = "Du har nu en |cffffd200kæledyrs handlingslinje|r for bedre kontrol over din dæmon. Du vil kunne tilkalde forskellige slags dæmoner til forskellige opgaver.",
    TUTORIAL7 = "Hvis du besejrer en fjende og ser glimt på dens lig, betyder det, at den har plyndring.|n|n|cffffd200Højreklik|r på et væsens lig for at plyndre det. Dette åbner et plyndringsvindue. Derefter |cffffd200højreklik|r på de genstande i vinduet for at flytte dem over i din rygsæk.",
    TUTORIAL8 = "En genstand er kommet i din rygsæk.|n|nDu kan klikke på |cffffd200Rygsæk-knappen|r nederst til højre på skærmen for at åbne din rygsæk.  Før musen hen over genstanden for at se, hvad den er.",
    TUTORIAL9 = "Nogle genstande kan bruges. |cffffd200Højreklik|r på en genstand for at bruge den.|n|nDu kan trække en genstand over på din handlingslinje, hvis du vil bruge den uden at åbne din rygsæk.",
    TUTORIAL_DRACTHYR_EMPOWERED_HOLD = "Jo længere du støber en styrket besværgelse, jo kraftigere bliver den.\\n\\n|cFF00FFFFHold nede|r din besværgelsestast for at begynde at støbe, og |cFF00FFFFslip|r for at besværge.",
    TUTORIAL_DRACTHYR_EMPOWERED_TAP = "Jo længere du støber en styrket besværgelse, jo kraftigere bliver den.\\n\\n|cFF00FFFFTryk|r på din besværgelsestast for at begynde at støbe, og |cFF00FFFFtryk igen|r for at besværge.",
    TUTORIAL_DRACTHYR_ESSENCE = "|cFF00FFFFEssens|r er en ressource, der bruges til besværgelser som |cFF00FFFFOpløs|r.\\n\\nDen genoprettes naturligt over tid.",
    TUTORIAL_DRACTHYR_SELF_CAST = "Hold |cFF00FFFF%s|r nede og støb |cFF00FFFFDen Levende Flamme|r for at hele dig selv",
    TUTORIAL_DRACTHYR_SELF_CAST_SETTINGS = "Du kan bruge |cFF00FFFFSelvbesværgelsestasten i Indstillinger|r for hurtigt at støbe Den Levende Flamme på dig selv",
    TUTORIAL_HERO_TALENT_NONE_SPENT = "Bare rolig, du lærer alle disse begavelser senest på niveau 80.",
    TUTORIAL_HUD_REVAMP_BAG_CHANGES = "Klik på dette ikon for at se nye filtre og muligheder for at samle taskerne.",
    TUTORIAL_HUD_REVAMP_LFG_QUEUE_CHANGES = "Du er i kø til en aktivitet.\\n\\nOplysninger om Gruppesøger-køen vises her.",
    TUTORIAL_HUD_REVAMP_TRACKING_CHANGES = "Sporingsmuligheder er blevet forenklet, og mange vil dukke op betinget, når det er relevant",
    TUTORIAL_HUD_REVAMP_UNIT_FRAME_CHANGES = "Spiller- og målenhedsrammerne er flyttet til en ny position.\\n\\nBrug Rediger Tilstand til at tilpasse UI-elementer på din skærmvisning ved at slå den til fra Vildtmenuen (esc).",
    TUTORIAL_PERKS_PROGRAM_ACTIVITIES_INTRO = "Rejs rundt i verden og fuldfør aktiviteter for at opnå |cFF00FFFFIndflydelse|r",
    TUTORIAL_PERKS_PROGRAM_ACTIVITIES_MAX_INFLUENCE = "Opnå nok |cFF00FFFFIndflydelse|r hver måned for at tjene betalingsmiddel og en særlig belønning i dit Samlerens Lager",
    TUTORIAL_PERKS_PROGRAM_ACTIVITIES_OPEN = "Se måder at tjene betalingsmiddel på i Rejsendes Logbog",
    TUTORIAL_PERKS_PROGRAM_ACTIVITIES_TRACKING = "Klik på aktiviteter for at følge dem i din Questlogbog",
    TUTORIAL_PERKS_PROGRAM_FREEZE_ITEM = "En frossen genstand forbliver tilgængelig måned efter måned, indtil den købes eller erstattes",
    TUTORIAL_PERKS_PROGRAM_HIDE_ARMOR = "Klik for at skifte synligheden af din rustning",
    TUTORIAL_PERKS_PROGRAM_NEW_COLLECTION_ITEM = "Du har nye genstande i din samling",
    TUTORIAL_PERKS_PROGRAM_OVERWRITE_FROZEN_ITEM = "Erstat din frosne genstand ved at trække en anden genstand herhen på et hvilket som helst tidspunkt",
    TUTORIAL_REAGENT_BAG_STEP_1 = "Du har fået en reagenstaske!|n|nÅbn din taske.",
    TUTORIAL_REAGENT_BAG_STEP_2 = "Udstyr din nye reagenstaske!|n|nAlle fremstillingsmaterialer, du samler op, havner i denne taske.",
    TUTORIAL_SUPERTRACK_STEP_1 = "Sæt fokus på en quest ved at klikke på dens ikon",
    TUTORIAL_TITLE1 = "Questgivere",
    TUTORIAL_TITLE10 = "Slå Dem Tilbage",
    TUTORIAL_TITLE11 = "Mad",
    TUTORIAL_TITLE12 = "Drik",
