    VOICEMACRO_18_Tr_2_FEMALE = "Vidunderligt.",
    VOICEMACRO_19_Dw_0 = "Nok af denne snak.  Lad os så komme i gang.",
    VOICEMACRO_19_Dw_0_FEMALE = "Jeg kan godt lide høje mænd.",
    VOICEMACRO_19_Dw_1 = "Du vil gerne løbe med hænderne gennem mit skæg, ikke?",
    VOICEMACRO_19_Dw_1_FEMALE = "Du skal vide, at jeg kan flade stål med mine lår.",
    VOICEMACRO_19_Dw_2 = "Lad os så komme i gang.  Jeg har en opgave at udføre om femten minutter.",
    VOICEMACRO_19_Dw_2_FEMALE = "Jeg vil gerne se dig i en kilt.",
    VOICEMACRO_19_Dw_3 = "Du ser pæn ud.  Jeg kan godt lide dit hår.  Her er din drink.  Er du klar nu?",
    VOICEMACRO_19_Dw_3_FEMALE = "Jeg falder ikke for enhver dårlig pickupline.  Du må prøve mindst to eller tre.",
    VOICEMACRO_19_Dw_4 = "Hvor kommer du fra?  Ikke at det betyder noget.",
    VOICEMACRO_19_Dw_4_FEMALE = "Nok med din flirt.  Jeg ved, at du tror alle dværgiske kvinder ser ens ud.",
    VOICEMACRO_19_Dw_5 = "Jeg må sove, for du er en drøm gået i opfyldelse.  Desuden er jeg lidt fugtig.",
    VOICEMACRO_19_Gn_0 = "Jeg har en række opfindelser, jeg gerne vil vise dig hjemme hos mig.",
    VOICEMACRO_19_Gn_0_FEMALE = "Du er nuttet.",
    VOICEMACRO_19_Gn_1 = "Alle bliver ved med at tale om ølbriller.  Jeg kan ingen steder finde tegningerne til dem.",
    VOICEMACRO_19_Gn_1_FEMALE = "På nuværende tidspunkt synes jeg, du bør købe en alkoholisk drik til mig og indlede en lille samtale med mig i håb om at skabe et fortroligt forhold.",
    VOICEMACRO_19_Gn_2 = "Jeg kan godt lide store bagdele, og jeg kan ikke sløre sandheden.",
    VOICEMACRO_19_Gn_2_FEMALE = "Din evne til at danne en hel sætning er et plus.",
    VOICEMACRO_19_Gn_3 = "Hey, flot apparat.",
    VOICEMACRO_19_Gn_3_FEMALE = "Jeg finder dig ikke helt usympatisk.",
    VOICEMACRO_19_Gn_4_FEMALE = "Jeg synes ikke, at skalaen fra 1 til 10 er fin nok til at fange de subtile detaljer i kompatibilitet.  Jeg foretrækker en 12-dimensionel kompatibilitetsskala med ekstra parametre for mekanisk evne og drejningsmoment.",
    VOICEMACRO_19_Hu_0 = "Hvordan har du det?",
    VOICEMACRO_19_Hu_0_FEMALE = "Du får mig helt i flimmer.",
    VOICEMACRO_19_Hu_1 = "Hvis jeg sagde, du havde en god krop, ville du så bebrejde mig det?",
    VOICEMACRO_19_Hu_1_FEMALE = "Mine afskrækkere er uhøflige folk, gemene folk og folk, der ikke er venlige.",
    VOICEMACRO_19_Hu_2 = "Hey, lille kage.",
    VOICEMACRO_19_Hu_2_FEMALE = "Jeg har brug for en helt.",
    VOICEMACRO_19_Hu_3 = "Hvad er dit stjernetegn?",
    VOICEMACRO_19_Hu_4 = "Er du træt, for du har løbet gennem mine tanker hele dagen.",
    VOICEMACRO_19_Hu_5 = "Dit mærke kigger frem.  Der står: \"Lavet i himlen.\"",
    VOICEMACRO_19_Ni_0 = "Du er Den Smaragdgrønne Drøm gået i opfyldelse.",
    VOICEMACRO_19_Ni_0_FEMALE = "Hvis jeg ikke var lilla, ville du kunne se, at jeg rødmer.",
    VOICEMACRO_19_Ni_1 = "Jeg håber, du ikke er bange for slanger.",
    VOICEMACRO_19_Ni_1_FEMALE = "Selvfølgelig har jeg eksotiske piercinger.",
    VOICEMACRO_19_Ni_2 = "Lille, jeg er dødelig nu.  Tiden løber.",
    VOICEMACRO_19_Ni_2_FEMALE = "Jeg er den slags pige, min mor advarede mig imod.",
    VOICEMACRO_19_Ni_3 = "Jeg er en kraft af natur.",
    VOICEMACRO_19_Ni_3_FEMALE = "Der er intet som at sove i skoven under månelyset.",
    VOICEMACRO_19_Ni_4 = "Vil du fremelske dyret i mig?",
    VOICEMACRO_19_Or_0 = "Den rustning klæder dig.  Den ville også klæde mit gulv.",
    VOICEMACRO_19_Or_0_FEMALE = "Du havde mig ved zug zug.",
    VOICEMACRO_19_Or_1 = "Dette er ægte kærlighed.  Tror du, det sker hvert døgn?",
    VOICEMACRO_19_Or_1_FEMALE = "Jeg giver dig gal kærlighed.",
    VOICEMACRO_19_Or_2 = "Du har seks forskellige smil; et for når du er vred, et for når du river kød, et for når du tygger kød, et for når du plyndrer lig, et for når du flår vildt, og et for når du vil dræbe noget.",
    VOICEMACRO_19_Or_2_FEMALE = "Jeg kan godt lide mænd, der ikke er bange for at græde; giv op, onkel.",
    VOICEMACRO_19_Or_3 = "Jeg elsker dig, som et fedt barn elsker kage.",
    VOICEMACRO_19_Or_3_FEMALE = "Du duer.  Lad os gå.",
    VOICEMACRO_19_Or_4 = "Dame, fra det øjeblik jeg så dig, jeg... jeg havde ikke forventet at komme så langt.",
    VOICEMACRO_19_Or_4_FEMALE = "Undlad at snakke, bare følg mig.",
    VOICEMACRO_19_Or_5 = "Øh, du ligner en dame.",
    VOICEMACRO_19_Or_5_FEMALE = "Lad os ikke ødelægge dette øjeblik med snak.",
    VOICEMACRO_19_Sc_0 = "Jeg lugter ikke så slemt for en død fyr, gør jeg?",
    VOICEMACRO_19_Sc_0_FEMALE = "Flot bagdel.",
    VOICEMACRO_19_Sc_1 = "Du har smuk hud; ingen ormehuller overhovedet.",
    VOICEMACRO_19_Sc_1_FEMALE = "En god ting ved at være død: det biologiske ur synes at være stoppet.",
    VOICEMACRO_19_Sc_2 = "Hvis råd var varmt, ville jeg være en vulkan.",
    VOICEMACRO_19_Sc_2_FEMALE = "Vi udøde piger ved virkelig, hvordan man har en god tid, for hvad er det værste, der kunne ske?",
    VOICEMACRO_19_Sc_3 = "Engang du er død, går du aldrig tilbage.",
    VOICEMACRO_19_Sc_3_FEMALE = "Jeg kan ikke vente med at suge saften ud af dine øjeæbler.",
    VOICEMACRO_19_Sc_4 = "Tjek min ånde.  Er den dårlig nok for dig?",
    VOICEMACRO_19_Sc_4_FEMALE = "Jeg bekymrer mig ikke så meget om romantik.  Jeg forelskede mig før, og se, hvad der skete med mig.",
    VOICEMACRO_19_Sc_5 = "Undlad at tage dig af savlen.  Det er bare balsameringsvæske.",
    VOICEMACRO_19_Sc_5_FEMALE = "Jeg behøver ikke at blive funky.  Jeg er allerede der.",
    VOICEMACRO_19_Ta_0 = "Du rører mig.",
    VOICEMACRO_19_Ta_0_FEMALE = "Jeg er træt af det samme gamle tyrekvas.",
    VOICEMACRO_19_Ta_1 = "Hey, er du til læder?",
    VOICEMACRO_19_Ta_1_FEMALE = "Jeg vil have en mand med bløde hænder.  Helst fire af dem.",
    VOICEMACRO_19_Ta_2 = "Fri kørsel til damerne.",
    VOICEMACRO_19_Ta_2_FEMALE = "Jeg har store, sjælfulde øjne, lange øjenvipper og en våd tunge.  Hvad mere kunne en fyr ønske sig?",
    VOICEMACRO_19_Ta_3 = "Hey, træner du?",
    VOICEMACRO_19_Ta_3_FEMALE = "Kom herhen, sømand.",
    VOICEMACRO_19_Ta_4 = "Du ved, ældre tyre har egentlig kun én funktion.",
    VOICEMACRO_19_Ta_4_FEMALE = "Vil du se lidt god træskodans?",
    VOICEMACRO_19_Ta_5 = "Er du tryg ved kompliceret maskineri?",
    VOICEMACRO_19_Tr_0 = "Vil du have noget af min junglekærlighed?",
    VOICEMACRO_19_Tr_0_FEMALE = "Jeg ved det.  Min naturlige skønhed er skræmmende.",
    VOICEMACRO_19_Tr_1 = "Vi Trolde parrer os for livet.  Selvfølgelig tror vi på hyppig genfødsel.",
    VOICEMACRO_19_Tr_1_FEMALE = "Når en hunlig Troll er rasende og i brunst, kan hun parre sig over firs gange på én nat.  Er du forberedt?",
    VOICEMACRO_19_Tr_2 = "Du ser pæn ud.  Pænt lækker.",
    VOICEMACRO_19_Tr_2_FEMALE = "Vil du ikke økse mig ud?",
    VOICEMACRO_19_Tr_3 = "Jeg håber, du er brønd udhvilet.  Du får brug for din styrke.",
    VOICEMACRO_19_Tr_3_FEMALE = "Jeg bider dig ikke, hvor det kan ses.",
